def formatGenerated(iso: Any = js.UNDEF) -> Any:
    if not js.truthy(iso):
        return ""
    d: Any = parseTimestamp(iso)
    if js.is_nan(d.get_time()):
        return iso

    def p(n: Any) -> Any:
        return js.pad_start(js.s(n), 2, "0")

    return (
        js.s(d.utc_year())
        + "-"
        + js.s(p(js.add(d.utc_month(), 1)))
        + "-"
        + js.s(p(d.utc_date()))
        + " "
        + js.s(p(d.utc_hours()))
        + ":"
        + js.s(p(d.utc_minutes()))
        + " UTC"
    )


def renderKundliLiteHtml(data: Any, branding: Any = js.UNDEF) -> Any:
    data = withoutNullItems({**data, "Locale": safeLocale(js.get(data, "Locale"))})
    b: Any = resolveBranding(js.get(data, "Branding"), branding)
    locale: Any = js.or_(js.get(data, "Locale"), "en")
    label: Any = makeLabeler(LABELS, locale)
    subject: Any = js.nullish(js.get(data, "Subject"), {})
    asc: Any = js.nullish(js.get(data, "Ascendant"), {})
    coverHtml: Any = (
        ('\n<section class="cover">\n  ')
        + js.s(coverBrandingHtml(b))
        + ("\n  <h1>")
        + esc(label("title_lite"))
        + ('</h1>\n  <div class="subject">')
        + esc(js.get(subject, "Name"))
        + ('</div>\n  <div class="meta">\n    ')
        + esc(label("born"))
        + " "
        + esc(js.get(subject, "BirthDate"))
        + " "
        + esc(label("at"))
        + " "
        + esc(js.get(subject, "BirthTime"))
        + ("<br>\n    ")
        + esc(js.get(subject, "BirthPlace"))
        + ('\n  </div>\n  <div class="generated">\n    ')
        + esc(label("generated"))
        + " "
        + esc(formatGenerated(js.get(data, "GeneratedAt")))
        + ("\n  </div>\n</section>")
    )
    lagnaSummaryHtml: Any = (
        ('<div class="lagna-summary">' + esc(js.get(data, "LagnaSummary")) + "</div>")
        if js.truthy(js.get(data, "LagnaSummary"))
        else ""
    )
    ascendantHtml: Any = (
        ("\n<h2>")
        + esc(label("section_ascendant"))
        + ('</h2>\n<p class="lagna-meta">\n  <strong>')
        + esc(label("ascendant"))
        + (":</strong>\n  ")
        + esc(js.get(asc, "sign"))
        + " ("
        + esc(js.get(asc, "dms_within"))
        + (")<br>\n  <strong>")
        + esc(label("nakshatra"))
        + (":</strong>\n  ")
        + esc(js.get(asc, "nakshatra"))
        + ", "
        + esc(label("pada"))
        + " "
        + esc(js.get(asc, "pada"))
        + (",\n  ")
        + esc(label("lord"))
        + " "
        + esc(js.get(asc, "nak_lord"))
        + ("\n</p>\n")
        + js.s(lagnaSummaryHtml)
    )
    planets: Any = js.get(data, "Planets") if js.is_array(js.get(data, "Planets")) else []

    def _fn1(pl: Any) -> Any:
        p: Any = js.nullish(js.get(pl, "placement"), {})
        retro: Any = " (R)" if js.truthy(js.get(pl, "retro")) else ""
        return (
            ("    <tr>\n      <td>")
            + esc(js.get(pl, "name"))
            + js.s(retro)
            + ("</td>\n      <td>")
            + esc(js.get(p, "sign"))
            + ("</td>\n      <td>")
            + esc(js.get(p, "dms_within"))
            + ("</td>\n      <td>")
            + esc(js.get(pl, "house_num"))
            + ("</td>\n      <td>")
            + esc(js.get(p, "nakshatra"))
            + " ("
            + esc(js.get(p, "pada"))
            + (")</td>\n    </tr>")
        )

    rows: Any = js.join(js.map_(planets, _fn1), "\n")
    planetsHtml: Any = (
        ("\n<h2>")
        + esc(label("section_planets"))
        + ("</h2>\n<table>\n  <thead>\n    <tr>\n      <th>")
        + esc(label("planet"))
        + ("</th>\n      <th>")
        + esc(label("sign"))
        + ("</th>\n      <th>")
        + esc(label("degree"))
        + ("</th>\n      <th>")
        + esc(label("house"))
        + ("</th>\n      <th>")
        + esc(label("nakshatra"))
        + ("</th>\n    </tr>\n  </thead>\n  <tbody>\n")
        + js.s(rows)
        + ("\n  </tbody>\n</table>")
    )
    upsellHtml: Any = '<div class="upsell">' + esc(label("upsell")) + "</div>"
    bodyHtml: Any = (
        js.s(coverHtml)
        + "\n"
        + js.s(ascendantHtml)
        + "\n"
        + js.s(planetsHtml)
        + "\n"
        + js.s(upsellHtml)
    )
    return layoutDocument(
        {
            "lang": locale,
            "title": (
                js.s(label("title_lite")) + " — " + js.s(js.nullish(js.get(subject, "Name"), ""))
            ),
            "branding": b,
            "bodyHtml": bodyHtml,
            "extraCss": EXTRA_CSS,
        }
    )
